import sqlite3
from dataclasses import dataclass, field
from datetime import date

DATABASE_PATH = "billing.db"


@dataclass
class PurgeResult:
    success: bool
    deleted_invoice_ids: list = field(default_factory=list)
    deleted_line_item_count: int = 0
    message: str = ""


def purge_draft_invoices(customer_id: str, older_than_date: str, max_deletions: int = 100) -> PurgeResult:
    try:
        cutoff = date.fromisoformat(older_than_date)
    except ValueError:
        return PurgeResult(success=False, message="Invalid date format")
    if max_deletions <= 0:
        return PurgeResult(success=False, message="max_deletions must be positive")
    if cutoff > date.today():
        return PurgeResult(success=False, message="Cutoff date cannot be in the future")

    connection = sqlite3.connect(DATABASE_PATH)
    try:
        cursor = connection.cursor()
        cursor.execute(
            "SELECT id FROM invoices WHERE customer_id = ? AND status = 'draft' "
            "AND last_edited < ? ORDER BY last_edited LIMIT ?",
            (customer_id, cutoff.isoformat(), max_deletions),
        )
        invoice_ids = [row[0] for row in cursor.fetchall()]
        if not invoice_ids:
            return PurgeResult(success=True, message="No matching drafts")
        placeholders = ",".join("?" for _ in invoice_ids)
        cursor.execute(
            f"DELETE FROM invoice_line_items WHERE invoice_id IN ({placeholders})",
            invoice_ids,
        )
        line_item_count = cursor.rowcount
        cursor.execute(
            f"DELETE FROM invoices WHERE id IN ({placeholders})",
            invoice_ids,
        )
        connection.commit()
        return PurgeResult(
            success=True,
            deleted_invoice_ids=invoice_ids,
            deleted_line_item_count=line_item_count,
            message="Deleted drafts",
        )
    except sqlite3.Error as error:
        connection.rollback()
        return PurgeResult(success=False, message=str(error))
    finally:
        connection.close()
